@lru_cache(maxsize=None)
def calc(n, m):
    if n == 0 or m == 0:
        return 0

    even_count = (m + 1) // 2
    odd_count = m // 2

    if n & 1:
        p = n // 2
        return m - calc(p, even_count) - calc(p + 1, odd_count)
    else:
        p = n // 2
